// Trước mắt: cố định UID bằng đúng giá trị cũ để đọc được dữ liệu đang có
public class CartSession implements Serializable {
    @Serial
    private static final long serialVersionUID = 5240751688771244621L;
    String userId;
    List<String> items = new ArrayList<>();
    String voucher;
}

